#!/usr/bin/env bash
# scripts/agent-run.sh — agent-driven verification harness driver
# Generated by /andromeda-setup-project Phase 4 from test-plan §3 + obs-plan §3.
# Maintenance: re-run /andromeda-setup-project after either plan changes.
#
# Conductor has NO daemon and NO inbound listener (test-plan §3) — boot is a preflight gate,
# status reads disk artifacts, there is no PID file:
#   boot     — MCP preflight readiness gate (conductor preflight --json; ready:true ⇒ exit 0,
#              ready:false ⇒ non-zero gate + dependent scenarios report Blocked)
#   run      — nextest + doctest + clippy (+ optional SCENARIO=/SEED= leg); stage flags
#              --unit | --integration | --e2e | --live (default: the full bundled gate), test-plan §9
#              --live is the operator-gated live-Pulse suite: never a CI gate, never reachable bare
#   status   — read the Run-report envelope from runs/<run_id>.jsonl (latest run if id omitted)
#   cleanup  — remove a run's artifacts + its runs.db row (idempotent); NEVER touches Pulse
#   logs     — print the per-run JSONL emission journal (latest run if id omitted)
#
# Bound contracts: test-plan §3 (5-command discipline, envelope, no PID file) · obs-plan §3 (JSONL format).

set -euo pipefail

CARGO="${CARGO:-cargo}"
RUNS_DIR="${CONDUCTOR_RUNS_DIR:-runs}"
UI_DIR="crates/conductor-tauri/ui"
RUN_CONTRACT="contracts/pulse-run-contract.toml"

# Read a bare `key = <integer>` term from the pinned run contract. A missing term is fatal, never
# defaulted: a silently-defaulted budget is how the wrapper came to be shorter than the run it guards.
run_contract_term() {
  local key="$1" value
  value="$(sed -n "s/^[[:space:]]*${key}[[:space:]]*=[[:space:]]*\([0-9][0-9]*\).*/\1/p" "$RUN_CONTRACT" | head -1)"
  if [ -z "$value" ]; then
    echo "boot: ${key} not found in ${RUN_CONTRACT}" >&2
    exit 2
  fi
  printf '%s' "$value"
}

# The `boot` wall-clock budget. CONDUCTOR_PREFLIGHT_TIMEOUT is the in-process canary POLL budget, which
# the contract's floor raises; the warm-up pre-roll runs BEFORE that poll starts, so a wrapper set to the
# poll alone kills the run mid-poll. Budget = warm-up + poll + margin (test-plan §3, contract
# [incident_formation]).
preflight_budget_sec() {
  local warmup_ms poll_floor poll
  warmup_ms="$(run_contract_term warmup_ms)"
  poll_floor="$(run_contract_term min_canary_poll_seconds)"
  poll="${CONDUCTOR_PREFLIGHT_TIMEOUT:-$poll_floor}"
  [ "$poll" -ge "$poll_floor" ] || poll="$poll_floor"
  printf '%s' "$(( warmup_ms / 1000 + poll + 30 ))"
}

# conductor-tauri's generate_context! resolves build.frontendDist (ui/dist) at COMPILE time, so the
# webview bundle must exist before any workspace cargo build/nextest/clippy compiles conductor-tauri
# (Epoch 9 frameless-window-shell). Install deps only when missing; always rebuild the bundle.
ensure_frontend() {
  ( cd "$UI_DIR" && { [ -d node_modules ] || npm ci; } && npm run build )
}

# A run_id is a filesystem-safe hyphen-delimited stamp; reject anything else before it reaches a path
# join or a sqlite3 statement (security-plan §Input Validation — no string-concat SQL on raw input).
valid_run_id() { [[ "$1" =~ ^[0-9A-Za-z._-]+$ ]]; }

# --- the operator-gated live suite (`run --live`) ------------------------------------------------
# The self-obs sink is TRUNCATING (conductor-core obs.rs) — every --agent-mode invocation wipes the
# previous leg's lines — so each leg's stream is frozen before the next one runs. A per-leg
# CONDUCTOR_RUNS_DIR would NOT separate them: the path resolves as runs_dir.parent()/logs, so every
# runs dir under runs/ lands in the same logs dir.
LIVE_LOG="$(dirname "$RUNS_DIR")/logs/agent-latest.jsonl"
LIVE_CAPTURE_DIR="$RUNS_DIR/live-suite"

# Total wall clock ≈ 12-15 min (B1 ~60s · B2 ~135s · quiet 150s · A ~215s · a11y ~3-4 min): each
# preflight pays the contract's warm-up before its poll starts, and a NOT-ready gate pays the whole
# poll floor. Per-leg budget = the preflight budget + the scenario's own phases + margin.
live_leg_budget_sec() { printf '%s' "$(( $(preflight_budget_sec) + ${1:-0} + 60 ))"; }

# Drive one scenario leg and freeze its self-obs under the capture dir. A Blocked row is a REPORTED
# state and exits 0 (only a hard Fail exits non-zero), which is what lets B2's deduped gate be an
# expected outcome rather than an abort under `set -e`.
live_leg() {
  local label="$1" scenario="$2" budget="$3"
  echo "[live] leg ${label}: ${scenario}"
  timeout "$budget" "$CARGO" run -q -p conductor-cli --bin conductor -- run "$scenario" --agent-mode
  mkdir -p "$LIVE_CAPTURE_DIR"
  if [ -f "$LIVE_LOG" ]; then
    cp "$LIVE_LOG" "$LIVE_CAPTURE_DIR/${label}.jsonl"
    echo "[live] leg ${label}: froze $(wc -l < "$LIVE_CAPTURE_DIR/${label}.jsonl") self-obs lines"
  else
    echo "[live] leg ${label}: no self-obs stream at ${LIVE_LOG}" >&2
  fi
}

live_suite() {
  # The probe leads and short-circuits: it is non-mutating and fires NO canary, so it primes none of
  # the incident state the legs then depend on. An unmet subject REFUSES the suite (each subject
  # named, host-path-free) rather than letting a partial env degrade to a ~0s [BLOCKED] row.
  if ! "$CARGO" run -q -p conductor-cli --bin conductor -- preconditions; then
    echo "run --live: refused — a live-Pulse precondition is unmet (above); no leg was fired" >&2
    exit 1
  fi

  # Clear last run's captures so an aborted run's stale leg file is never mis-read as this run's.
  # Non-recursive by design: the dir holds only the leg files this script writes, so the `cleanup`
  # verb's idiom (rm -f on named artifacts) covers it without a recursive delete over a path derived
  # from an operator-supplied handle.
  mkdir -p "$LIVE_CAPTURE_DIR"
  rm -f "$LIVE_CAPTURE_DIR"/*.jsonl

  # live_leg_order — B1 and B2 are the SAME short scenario fired twice on purpose.
  #   B1  gate ready; read-back finds its own canary incident still open -> a graded manual row.
  #   B2  fired immediately, inside Pulse's 120s idle window: its canary dedupes against B1's still-open
  #       incident on the (kind, scope, scope_id) tuple, no fresh incident forms, and the gate goes
  #       not-ready-but-CONNECTED — the only state that reaches the readiness-gate self-obs line.
  #       ANDROMEDA_PULSE_L4_DETERMINISTIC is load-bearing here: canned-L4 formation is ~2s, so B2's
  #       storm lands well inside the window; real-model formation (~110s) would fall outside it.
  #   A   after the quiet window, a fresh canary forms and then idles for the whole silent scenario,
  #       so read-back finds an EMPTY active set — the auto-resolve residual arm.
  live_leg b1 degraded-mode-report "$(live_leg_budget_sec 10)"
  live_leg b2 degraded-mode-report "$(live_leg_budget_sec 10)"

  echo "[live] quiet window: 150s (Pulse's 120s idle + a 30s resolver tick) before leg a"
  sleep 150

  live_leg a auto-resolve-idle-window "$(live_leg_budget_sec 180)"

  # The driven a11y arm fires its own preflight canary; leg A's canary has already resolved by A's
  # read-back, so no extra window is needed. It self-skips at exit 0 when no native WebDriver resolves
  # (wdio.conf.ts guards CONDUCTOR_MSEDGEDRIVER), which is a SKIP, not a refusal — a host-tool handle
  # and a live-Pulse handle are different classes.
  echo "[live] driven a11y arm"
  ensure_frontend
  "$CARGO" build --release -p conductor-tauri --features tauri/custom-protocol
  ( cd "$UI_DIR" && npm run a11y:driven )

  echo "[live] suite complete — captures under $LIVE_CAPTURE_DIR"
  echo "[live] stop form: the wdio arm self-terminates via onComplete -> tauriDriver.kill(); after an"
  echo "[live] interrupted run: taskkill /F /IM msedgedriver.exe /IM conductor-tauri.exe (+ the node CLI)."
  echo "[live] pulse-app is NOT stopped here — the operator started it and stops it."
}

# The newest run's id — the lexicographically greatest <run_id>.jsonl stem (run_ids sort by time).
latest_run_id() {
  local f stem newest=""
  for f in "$RUNS_DIR"/*.jsonl; do
    [ -e "$f" ] || continue
    stem="$(basename "$f" .jsonl)"
    if [[ "$stem" > "$newest" ]]; then newest="$stem"; fi
  done
  printf '%s' "$newest"
}

case "${1:-}" in
  boot)
    # ready:true ⇒ exit 0; ready:false ⇒ non-zero (gate) + dependent scenarios Blocked (never a silent
    # downgrade). With no live Pulse this is ready:false — so the CI gate dogfoods `run`, not `boot`;
    # the live-Pulse leg needs Pulse's mcp-server feature + ANDROMEDA_PULSE_MCP_ENABLED + a matching
    # ANDROMEDA_PULSE_DATA_DIR.
    #
    # The precondition probe runs FIRST and short-circuits, SKIPPING the preflight rather than paying
    # it: an unmet launch condition explains a failed canary, so surfacing the canary symptom first
    # sends the operator to the wrong cause and spends the whole budget doing it (the arch ordering
    # rationale for the fifth named precondition, applied one rung earlier). The probe fires no
    # canary, so it primes none of the state the preflight then dedupes against.
    if ! "$CARGO" run -q -p conductor-cli --bin conductor -- preconditions; then
      echo "boot: skipped preflight — a live-Pulse precondition is unmet (above)" >&2
      exit 1
    fi
    timeout "$(preflight_budget_sec)" "$CARGO" run -q -p conductor-cli --bin conductor -- preflight --json
    ;;

  run)
    # Stage flags partition the CI gate (test-plan §9); no flag = the full bundled gate.
    case "${2:-}" in
      --unit)        ensure_frontend; "$CARGO" nextest run --workspace --profile ci ;;
      --integration) ensure_frontend; "$CARGO" nextest run --workspace --profile ci -E 'kind(test)' ;;
      # test-plan §3/§9: --e2e IS the tauri-driver `wdio run` leg. The bundle must be built before the
      # compile (generate_context! resolves frontendDist at compile time), and the binary must embed
      # it rather than loading tauri.conf.json's devUrl. What decides that is the `custom-protocol`
      # FEATURE, not the profile: tauri's build.rs computes `dev = !custom_protocol` and tauri-build
      # reads it back through DEP_TAURI_DEV, so a bare `--release` build still loads localhost:5173
      # (measured 2026-09-01). The leg skips at exit 0 when no native WebDriver resolves (wdio.conf.ts).
      --e2e)
        ensure_frontend
        "$CARGO" build --release -p conductor-tauri --features tauri/custom-protocol
        ( cd "$UI_DIR" && npm run a11y )
        ;;
      "")
        ensure_frontend
        "$CARGO" nextest run --workspace --profile ci
        "$CARGO" test --workspace --doc
        "$CARGO" clippy --workspace --all-targets -- -D warnings
        # Optional scenario leg: SCENARIO=<name|P-ID> [SEED=<n>] scripts/agent-run.sh run
        # --agent-mode: JSON self-obs to logs/agent-latest.jsonl + never block on an operator pause.
        # --seed rides ONLY an explicitly set SEED — files-over-env-defaults precedence (arch
        # §Config management): the TOML-declared seed governs when SEED is unset.
        if [ -n "${SCENARIO:-}" ]; then
          if [ -n "${SEED:-}" ]; then
            "$CARGO" run -q -p conductor-cli --bin conductor -- run "$SCENARIO" --seed "$SEED" --agent-mode
          else
            "$CARGO" run -q -p conductor-cli --bin conductor -- run "$SCENARIO" --agent-mode
          fi
        fi
        ;;
      # test-plan §9: the operator-gated live suite. NEVER a CI gate and never reachable from a bare
      # `run` — a live leg drives a real Pulse. Composes B1 → B2 → quiet window → A → the driven a11y
      # arm, in that order, because each leg's outcome depends on the incident state the previous one
      # left (see live_leg_order below).
      --live)
        live_suite
        ;;
      *) echo "usage: $0 run [--unit|--integration|--e2e|--live]" >&2; exit 2 ;;
    esac
    ;;

  status)
    # Read the Run-report envelope from disk — there is no listener to poll.
    id="${2:-}"
    [ -n "$id" ] || id="$(latest_run_id)"
    [ -n "$id" ] || { echo "status: no run found in $RUNS_DIR" >&2; exit 1; }
    valid_run_id "$id" || { echo "status: invalid run_id" >&2; exit 2; }
    journal="$RUNS_DIR/$id.jsonl"
    [ -f "$journal" ] || { echo "status: no journal for run_id=$id" >&2; exit 1; }
    # Last line carries the final envelope; assert it parses and surface verdict/state.
    tail -n 1 "$journal" | jq -e '{run_id, seed, scenario, verdict, state, latency_ms, slo_tier}'
    ;;

  cleanup)
    # Idempotent: remove a run's artifacts + its runs.db row. NEVER touch Pulse (no process management);
    # the :4317 port-occupier is RAII-released when the conductor process exits.
    id="${2:-}"
    if [ -n "$id" ]; then
      valid_run_id "$id" || { echo "cleanup: invalid run_id" >&2; exit 2; }
      rm -f "$RUNS_DIR/$id.jsonl" "$RUNS_DIR/$id.md"
      if [ -f "$RUNS_DIR/runs.db" ] && command -v sqlite3 >/dev/null 2>&1; then
        sqlite3 "$RUNS_DIR/runs.db" "DELETE FROM runs WHERE run_id = '$id';" 2>/dev/null || true
      fi
    fi
    echo "cleanup: done${id:+ ($id)}"
    ;;

  logs)
    # The emission journal is ground truth — print it (JSONL, one envelope per line).
    id="${2:-}"
    [ -n "$id" ] || id="$(latest_run_id)"
    [ -n "$id" ] || { echo "logs: no run found in $RUNS_DIR" >&2; exit 1; }
    valid_run_id "$id" || { echo "logs: invalid run_id" >&2; exit 2; }
    [ -f "$RUNS_DIR/$id.jsonl" ] || { echo "logs: no journal for run_id=$id" >&2; exit 1; }
    cat "$RUNS_DIR/$id.jsonl"
    ;;

  *)
    echo "Usage: $0 {boot|run [--unit|--integration|--e2e|--live]|status [run_id]|cleanup [run_id]|logs [run_id]}" >&2
    exit 2
    ;;
esac
